BEGIN;
DO $test$
DECLARE h uuid:=gen_random_uuid();ad uuid;other_ad uuid;kid uuid;outsider uuid;ids uuid[];d date:=(now() AT TIME ZONE 'America/New_York')::date;p jsonb;c jsonb;r jsonb;plan_id uuid:=gen_random_uuid();fact_id uuid;old_payload jsonb;old_fingerprint text;n integer;
BEGIN
 SELECT array_agg(user_id ORDER BY user_id) INTO ids FROM (SELECT DISTINCT user_id FROM public.bb_planner_members LIMIT 4) x;ad:=ids[1];other_ad:=ids[2];kid:=ids[3];outsider:=ids[4];IF outsider IS NULL THEN RAISE EXCEPTION 'Missing test identities';END IF;
 INSERT INTO public.bb_planner_households(id,label) VALUES(h,'Finance rollback test');
 INSERT INTO public.bb_planner_members(household_id,user_id,member_role) VALUES(h,ad,'adult'),(h,other_ad,'adult'),(h,kid,'child');
 INSERT INTO public.bb_finance_records(household_id,entity_key,kind,payload,effective_start,status,source,needs_confirmation) VALUES(h,'fixture-account','account','{"name":"Fixture spending","household_usable":true,"buffer_min_cents":10000}',d,'active','Test',false);
 INSERT INTO public.bb_finance_records(household_id,entity_key,kind,payload,effective_start,status,source,needs_confirmation)
 SELECT h,'fixture-'||name,'bill_instance',jsonb_build_object('name',name,'account','Fixture spending','due_date',CASE WHEN name='outside' THEN d+15 ELSE d+1 END,'amount_cents',amount,'payment_status',state,'allocation_class',kind,'certainty','exact'),d,'active','Test',false FROM (VALUES('bill',10000,'confirmed','bill'),('pending',3000,'pending','bill'),('minimum',2000,'scheduled','debt_minimum'),('paid',4000,'paid','bill'),('outside',5000,'confirmed','bill')) x(name,amount,state,kind);
 p:=jsonb_build_object('name','Fictional check','account_key','fixture-account','received_on',d,'next_payday',d+14,'cash_as_of',d,'available_cash_cents',200000,'protected_other_cents',10000,'food_cents',30000,'gas_cents',10000,'laundry_cents',5000,'other_living_cents',5000,'buffer_cents',20000,'utilization_cents',10000,'savings_cents',5000,'extra_debt_cents',0,'cash_confirmed',true,'living_confirmed',true,'obligations_reviewed',true,'buffer_exception',false,'source_note','Fictional verified test inputs only');
 PERFORM set_config('request.jwt.claim.sub',ad::text,true);EXECUTE 'SET LOCAL ROLE authenticated';
 c:=public.bb_finance_preview(h,p);
 IF c->>'required_cents'<>'15000' OR c->>'minimums_cents'<>'2000' OR c->>'living_cents'<>'50000' OR c->>'unassigned_cents'<>'90000' OR jsonb_array_length(c->'blockers')<>0 OR jsonb_array_length(c->'items')<>4 THEN RAISE EXCEPTION 'Wrong exact-cents/window/paid/pending calculation: %',c;END IF;
 r:=public.bb_finance_plan_save(h,plan_id,NULL,p,false,c->>'source_fingerprint');IF r->>'status'<>'draft' THEN RAISE EXCEPTION 'Draft not saved';END IF;
 PERFORM set_config('request.jwt.claim.sub',other_ad::text,true);SELECT count(*) INTO n FROM public.bb_finance_check_plans WHERE id=plan_id;IF n<>1 THEN RAISE EXCEPTION 'Other adult cannot read';END IF;
 r:=public.bb_finance_plan_save(h,plan_id,1,p,true,c->>'source_fingerprint');IF r->>'status'<>'approved' OR r->>'approved_by'<>other_ad::text THEN RAISE EXCEPTION 'Approval attribution';END IF;
 BEGIN PERFORM public.bb_finance_plan_save(h,plan_id,1,p,false,c->>'source_fingerprint');RAISE EXCEPTION 'Stale plan accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 c:=public.bb_finance_preview(h,p||'{"available_cash_cents":null}');IF c->>'unassigned_cents' IS NOT NULL OR jsonb_array_length(c->'blockers')=0 OR jsonb_array_length(c->'scenarios')<>0 THEN RAISE EXCEPTION 'Unknown cash inferred';END IF;
 BEGIN PERFORM public.bb_finance_plan_save(h,gen_random_uuid(),NULL,p||'{"available_cash_cents":null}',true,c->>'source_fingerprint');RAISE EXCEPTION 'Unknown approved';EXCEPTION WHEN object_not_in_prerequisite_state THEN NULL;END;
 c:=public.bb_finance_preview(h,p||'{"available_cash_cents":1}');IF (c->>'base_remaining_cents')::bigint>=0 OR jsonb_array_length(c->'blockers')=0 THEN RAISE EXCEPTION 'Shortfall hidden';END IF;
 c:=public.bb_finance_preview(h,p||'{"available_cash_cents":-100}');IF c->>'cash_cents'<>'-100' OR jsonb_array_length(c->'blockers')=0 THEN RAISE EXCEPTION 'Overdraft hidden';END IF;
 BEGIN PERFORM public.bb_finance_preview(h,p||'{"available_cash_cents":1.5}');RAISE EXCEPTION 'Fractional cents accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.bb_finance_preview(h,p||'{"future_paycheck_cents":100}');RAISE EXCEPTION 'Unknown cash field accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 SELECT id,payload INTO fact_id,old_payload FROM public.bb_finance_records WHERE household_id=h AND entity_key='fixture-bill' AND is_current;
 old_fingerprint:=public.bb_finance_preview(h,p)->>'source_fingerprint';r:=public.bb_finance_fact_revise(h,fact_id,1,'{"amount_cents":12000}',true,true,d,'Verified revised amount in fictional source');
 IF r->>'version'<>'2' OR (r->'payload'->>'amount_cents')<>'12000' THEN RAISE EXCEPTION 'Fact revision failed';END IF;
 SELECT count(*) INTO n FROM public.bb_finance_records WHERE id=fact_id AND payload=old_payload AND NOT is_current AND superseded_by=(r->>'id')::uuid;IF n<>1 THEN RAISE EXCEPTION 'Old payload/history lost';END IF;
 BEGIN PERFORM public.bb_finance_fact_revise(h,fact_id,1,'{"amount_cents":13000}',true,true,d,'Stale test source should fail');RAISE EXCEPTION 'Stale fact accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.bb_finance_plan_save(h,plan_id,2,p,true,old_fingerprint);RAISE EXCEPTION 'Stale source approval accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.bb_finance_fact_revise(h,(r->>'id')::uuid,2,'{"household_id":"tamper"}',true,true,d,'Identity tamper should fail');RAISE EXCEPTION 'Tamper accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 SELECT id INTO fact_id FROM public.bb_finance_records WHERE household_id=h AND entity_key='fixture-pending' AND is_current;
 r:=public.bb_finance_fact_revise(h,fact_id,1,'{"already_deducted":true,"deducted_as_of":null}',true,true,d,'Fictional pending hold needs snapshot date');c:=public.bb_finance_preview(h,p);IF c->>'required_cents'<>'17000' OR jsonb_array_length(c->'blockers')=0 THEN RAISE EXCEPTION 'Missing deduction date dropped obligation';END IF;
 r:=public.bb_finance_fact_revise(h,(r->>'id')::uuid,2,jsonb_build_object('deducted_as_of',d),true,true,d,'Fictional pending hold included in verified cash snapshot');c:=public.bb_finance_preview(h,p);IF c->>'required_cents'<>'14000' THEN RAISE EXCEPTION 'Pending deduction counted twice';END IF;
 PERFORM set_config('request.jwt.claim.sub',kid::text,true);SELECT count(*) INTO n FROM public.bb_finance_records WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Child fact leak';END IF;SELECT count(*) INTO n FROM public.bb_finance_check_plans WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Child plan leak';END IF;SELECT count(*) INTO n FROM public.bb_finance_changes WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Child audit leak';END IF;
 BEGIN PERFORM public.bb_finance_preview(h,p);RAISE EXCEPTION 'Child preview allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.bb_finance_plan_save(h,plan_id,2,p,false,old_fingerprint);RAISE EXCEPTION 'Child write allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.bb_finance_fact_revise(h,fact_id,1,'{}',true,true,d,'Child fact write should fail');RAISE EXCEPTION 'Child fact write allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',outsider::text,true);SELECT count(*) INTO n FROM public.bb_finance_check_plans WHERE household_id=h;IF n<>0 THEN RAISE EXCEPTION 'Foreign plan leak';END IF;
 BEGIN PERFORM public.bb_finance_preview(h,p);RAISE EXCEPTION 'Foreign preview allowed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 PERFORM set_config('request.jwt.claim.sub',ad::text,true);
 r:=public.bb_finance_bill_create(h,gen_random_uuid(),jsonb_build_object('name','New fictional dated bill','account','Fixture spending','due_date',d+2,'amount_cents',1234,'payment_status','confirmed','certainty','exact','allocation_class','bill'),d,true,'Checked a new fictional invoice');
 c:=public.bb_finance_preview(h,p);IF c->>'required_cents'<>'15234' THEN RAISE EXCEPTION 'New/revised bill not included once';END IF;
 r:=public.bb_finance_fact_revise(h,(r->>'id')::uuid,1,'{}',false,true,d,'Fictional cancellation verified');c:=public.bb_finance_preview(h,p);IF c->>'required_cents'<>'14000' THEN RAISE EXCEPTION 'Inactive bill still included';END IF;
 EXECUTE 'SET LOCAL ROLE postgres';
 IF has_table_privilege('authenticated','public.bb_finance_check_plans','UPDATE') OR has_table_privilege('authenticated','public.bb_finance_records','INSERT') OR has_function_privilege('anon','public.bb_finance_preview(uuid,jsonb)','EXECUTE') THEN RAISE EXCEPTION 'Direct write/anon ACL exposure';END IF;
 SELECT count(*) INTO n FROM public.bb_finance_changes WHERE household_id=h;IF n<>7 THEN RAISE EXCEPTION 'Wrong audit count';END IF;
 RAISE NOTICE 'PASS exact cents, window, paid/pending, minimum once, revisions, stale sources, approval, unknown/shortfall, role isolation, ACLs, attribution/history';
END $test$;
ROLLBACK;
